(window.TNQ=window.TNQ||[]).push({"terms":{"가소성":{"d":"경험과 훈련에 따라 뇌와 행동이 변화할 수 있는 성질입니다.","r":[]},"규범적 역사관련 요인":{"d":"같은 시대를 사는 사람들이 거의 동시에 겪는 역사적 사건의 영향으로 발달에 작용하는 요인입니다.","r":[]},"관찰자 편향":{"d":"관찰자의 기대나 선입견이 관찰과 해석에 영향을 주어 결과가 왜곡되는 현상입니다.","r":[]},"기관생명윤리위원회":{"d":"사람을 대상으로 하는 연구가 윤리 원칙에 맞는지 심의하는 기관 내 위원회입니다.","r":[]},"심리적 결정론":{"d":"인간의 모든 생각과 행동에는 심리적 원인이 있어 우연히 일어나는 것이 없다는 가정입니다.","r":[]},"방어기제":{"d":"불안을 줄이기 위해 무의식적으로 현실을 왜곡하거나 감정을 처리하는 자아의 방식입니다.","r":["망상적 투사"]},"망상적 투사":{"d":"자신의 충동이나 감정을 타인에게 있다고 여기며 현실을 심하게 왜곡하는 정신병적 방어기제입니다.","r":["방어기제"]},"기초정신능력이론":{"d":"써스톤이 지능을 서로 독립적인 여러 기본 능력으로 구성된다고 설명한 이론입니다.","r":[]},"이요인이론":{"d":"스피어만이 지능을 모든 과제에 쓰이는 일반요인과 특정 과제에만 쓰이는 특수요인으로 설명한 이론입니다.","r":["일반요인"]},"일반요인":{"d":"스피어만이 모든 유형의 지적 활동에 공통으로 작용한다고 본 지능의 요인입니다.","r":["이요인이론"]},"다중지능이론":{"d":"가드너가 지능을 서로 독립적인 여러 가지 지능으로 구성된다고 본 이론입니다.","r":[]},"변연계":{"d":"편도체 등을 포함해 정서와 기억, 동기에 관여하는 뇌의 영역입니다.","r":["편도체"]},"편도체":{"d":"변연계에 속하며 공포와 분노 같은 정서 반응에 관여하는 뇌 구조입니다.","r":["변연계"]},"시냅스":{"d":"뉴런과 뉴런이 정보를 주고받는 접합 부위입니다.","r":[]},"전전두엽":{"d":"이마 쪽 대뇌 피질로 계획, 판단, 충동 조절 같은 인지적 통제에 관여합니다.","r":[]},"과잉확장":{"d":"아이가 단어를 실제 의미보다 넓은 범위의 대상에 사용하는 어휘발달 초기의 특성입니다.","r":[]},"언어습득장치":{"d":"촘스키가 인간이 언어를 배울 수 있도록 타고난다고 가정한 선천적 기제입니다.","r":[]},"만족지연":{"d":"더 큰 보상을 위해 당장의 욕구 충족을 참고 미루는 능력입니다.","r":[]},"도구적 공격성":{"d":"물건이나 목표를 얻으려는 수단으로 쓰는 공격 행동입니다.","r":[]},"조합적 추리":{"d":"여러 요인을 체계적으로 짝지어 가능한 경우를 모두 따져 보는 형식적 조작기의 사고 능력입니다.","r":[]},"마음이론":{"d":"타인도 자신과 다른 생각과 믿음과 의도를 가진다는 것을 이해하는 능력입니다.","r":[]},"대상영속성":{"d":"대상이 눈앞에서 사라져도 계속 존재한다는 것을 아는 능력입니다.","r":[]}},"notes":{"8단계인 노년기에 발달되는 바람직한 미덕으로 지혜를 제안한다":"에릭슨은 마지막 단계에서 통합을 이루면 지혜라는 미덕을 얻는다고 했습니다.","C. Spearman의 이요인이론":"스피어만이 지능을 일반요인과 특수요인으로 본 이론의 이름입니다.","H. Gardner의 다중지능이론":"가드너가 지능을 여러 종류로 나눈 이론의 이름입니다.","I. Thurstone의 기초정신능력이론":"써스톤의 기초정신능력이론이라는 이름을 소개하는 문장입니다.","R. Cattell의 Gf-Gc이론":"카텔이 지능을 유동지능과 결정지능으로 나눈 이론의 이름입니다.","U. Bronfenbrenner":"생태학적 체계 이론을 세운 학자의 이름 표기입니다.","activity theory":"활동 이론을 가리키는 영어 용어로, 노인이 활동을 지속해야 만족스러운 노화를 맞는다는 관점입니다.","disengagement theory":"유리 이론을 가리키는 영어 용어로, 노인이 사회와 서로 거리를 두는 것이 자연스럽다고 봅니다.","갑자기 위치가 바뀌거나 큰 소리가 들리면 나타난다":"모로 반사는 몸이 갑자기 흔들리거나 큰 소리가 날 때 팔을 벌렸다 오므리는 반응입니다.","개인과 생태학적 체계 간의 관계는 양방향적이다":"환경이 개인에게 영향을 주고 개인도 환경에 영향을 준다는 상호성을 강조합니다.","개인생활과 직업생활에서 미성숙한 방어기제보다는 더 성숙한 방어기제를 사용하는 쪽으로 이동":"잘 적응한 사람들은 시간이 갈수록 덜 미숙한 방어기제를 쓰는 쪽으로 옮겨 갔다는 결과입니다.","결정적 지능(Gc)은 성인기에도 다양한 지적 자극을 통해":"결정적 지능이 성인기에 어떻게 되는지를 설명하는 문장의 앞부분입니다.","경험에 반응하여 변화하는 능력을 의미한다":"가소성은 경험을 받아들여 뇌나 행동이 달라질 수 있는 능력입니다.","공간지각 및 추론 능력과 관련된다":"도형을 머릿속에서 다루고 추리하는 능력으로, 유동지능과 이어지는 특성입니다.","공격성이 잘못된 사회인지적 판단에 기인한다고 본다":"애매한 상황을 적대적 의도로 해석하는 판단 오류가 공격 행동을 불러일으킨다고 설명합니다.","공격적 행동은 그러한 행동이 결과적으로 공격자에게 보상을 가져다주기 때문에 발달한다고 주장한다":"공격해서 원하는 것을 얻은 경험이 쌓이면 그 행동이 강화되어 굳어진다는 설명입니다.","과잉확장과 과잉축소의 특성이 나타난다":"아이가 네발 동물을 모두 멍멍이라 부르거나 자기 집 개만 개라고 하는 식의 오류가 생깁니다.","관찰자가 자신이 원하는 방식으로 관찰 자료를 수집하고 해석하는 관찰자 편향이 나타날 수 있다":"기대한 대로 보고 해석하려는 경향 때문에 관찰법의 결과가 왜곡될 수 있습니다.","그들이 표현하는 정서를 잘 구별하지 못한다":"겉으로 드러낸 감정과 속마음이 다를 수 있다는 점을 아직 이해하지 못합니다.","근로자, 부모 등 개인의 역할이 삶에서 만족을 얻을 수 있는 주요 원천으로 본다":"활동 이론은 역할을 유지할수록 삶의 만족이 높아진다고 이해합니다.","기형유발물질에 의한 중추신경계 손상에 가장 민감한 시기이다":"배아기는 장기가 만들어지는 때여서 해로운 물질에 노출되면 신경계에 가장 큰 피해를 입습니다.","남성을 대상으로 연구한 결과를 근거로 하였다":"이 이론은 남성만을 연구해 얻은 자료에 바탕을 두어 여성에게 그대로 적용하기 어렵다는 한계가 있습니다.","노년기를 ‘다리 위에서의 조망(one's view from the bridge)’이라 표현 한다":"레빈슨은 노년기를 지나온 삶을 돌아보며 앞날을 바라보는 시기로 비유합니다.","노년기에도 가소성(plasticity)으로 인해 · 훈련과 연습을 하면 다양한 기술을 향상시킬 수 있다":"나이가 들어도 뇌와 행동이 바뀔 수 있어서 연습하면 기능이 좋아집니다.","노인과 사회의 상호 철회 과정을 부정적으로 보지 않고 성공적 노화로 본다":"노인과 사회가 서로 물러나는 것을 문제로 보지 않고 바람직한 적응으로 평가합니다.","눈 깜박이기 반사나 호흡 반사와 같은 생존 반사는 평생 유지된다":"생명 유지와 직결되는 반사는 다른 원시 반사와 달리 사라지지 않고 계속 남습니다.","다섯 단계로 이루어지는 성격발달단계는 누구든 차례대로 거치게 된다":"프로이트의 성격발달은 정해진 순서가 있어 누구나 같은 차례로 지납니다.","단점으로는 피험자 탈락, 편파적 표집 및 연습효과 등을 들 수 있다":"같은 사람을 오래 따라가는 방법이라 중도에 떠나는 사람이 생기고 반복 측정에 익숙해집니다.","대뇌 피질의 발달은 영아기 이후에도 진행된다":"대뇌 피질은 영아기에 끝나지 않고 그 뒤로도 계속해서 성숙합니다.","독립변수와 종속변수 간의 인과관계를 파악한다":"독립변수를 조작했을 때 종속변수가 달라지는지 보아 원인과 결과를 확인합니다.","동시에 각기 다른 연령의 사람들을 비교하여 연구하는 방법이다":"한 시점에 여러 연령 집단을 조사해 연령 차이를 보므로 비교적 빨리 끝납니다.","두 변수 간 원인과 결과의 관계를 알 수 있다":"실험은 조건을 통제해서 한 변수가 다른 변수를 일으키는지 판단할 수 있습니다.","둘 이상의 변수 간 관계를 상관계수로 표현한다":"변수들이 함께 변하는 정도를 수치로 나타내는 방법으로 인과관계는 말해 주지 않습니다.","마음이론을 발달시키지 못해 다른 사람의 관점을 잘 이해하지 못한다":"남의 생각과 의도를 추론하는 능력이 부족해서 사회적 관계에서 어려움을 겪습니다.","망상적 투사, 부정, 왜곡이 대표적 유형":"현실 판단을 크게 잃게 하는 정신병적 방어기제의 대표 종류입니다.","머리에서 발 방향으로 진행된다":"신체 발달은 머리 쪽이 먼저 이루어지고 아래쪽이 나중에 이루어지는 두미 방향을 따릅니다.","명제적 사고와 가설 연역적인 논리적 사고를 할 수 있다":"눈앞에 없는 진술과 가정에서 출발해 결론을 이끌어 내는 사고를 하게 됩니다.","모든 연령에서의 발달은 성장과 감소의 변화가 함께 일어난다":"어느 시기든 얻는 것과 잃는 것이 동시에 있어 발달을 성장만으로 설명할 수 없습니다.","문제 해결에 필요한 요인만 골라내어":"청소년기 사고의 특징을 설명하는 문장의 앞부분으로, 문제 해결에 필요한 요인을 선별합니다.","발달은 생명의 시작에서 죽음에 이르기까지의 · 전 생애 동안 이루어지는 모든 과정이다":"발달은 아동기에 그치지 않고 태어나서 죽을 때까지 평생에 걸쳐 일어납니다.","발달은 유전과 환경의 상호작용 결과이다":"타고난 것과 자라는 환경 둘 중 하나가 아니라 서로 영향을 주고받아 발달이 결정됩니다.","발달을 구별되는 단계로 일어나는 질적 변화의 과정으로 본다":"발달을 양이 늘어나는 연속적 과정이 아니라 단계마다 종류가 달라지는 변화로 이해하는 관점입니다.","방어기제를 습관적으로 반복 사용하는 것은 건강하지 못한 성격의 징표로 볼 수 있다":"불안을 피하려고 같은 방어기제만 굳어지게 쓰면 현실 대처가 어려워진다는 의미입니다.","변연계 중 편도체는 정서와 감정을 관장한다":"편도체는 두려움 같은 정서 반응을 처리하는 변연계의 구조입니다.","사전 동의를 받았더라도 연구 과정에서 예기치 못한 위협이 발생할 경우 연구자는 즉시 연구를 중단해야 한다":"참여자가 처음 동의했어도 예상 밖의 위험이 생기면 연구자는 즉시 멈추어야 합니다.","사회적ㆍ정서적 상호작용에서 결함을 보인다":"다른 사람과 감정을 나누고 대화를 주고받는 데 지속적인 어려움이 있습니다.","사회적 맥락에서 언어를 적절하고 효과적으로 사용하는 규칙에 관한 지식이다":"문법 지식을 넘어 상황과 상대에 맞게 말하는 방법을 아는 것을 뜻합니다.","새로운 문제를 다루는 능력이다":"낯선 문제를 풀 때 쓰는 추론 능력을 말하며 유동지능의 특성으로 설명됩니다.","성인 중기 전후에 퇴보하기 시작한다":"이 지능은 성인 중기 무렵부터 서서히 떨어지기 시작합니다.","시각피질의 시냅스 생성은 출생 후 1년까지 활발하게 진행된다":"영아기에는 보는 것을 담당하는 부위에서 신경 연결이 빠르게 늘어납니다.","시련이나 위기에 직면한 개인이 나타내는 심리적 적응방식에서의 발달적 변화에 관심":"어려움을 만났을 때 쓰는 대처 방식이 나이에 따라 어떻게 달라지는지를 연구했습니다.","신생아는 출생 직후부터 외부 자극에 무의식적으로 반응한다":"신생아의 반사는 의도 없이 자극에 자동으로 일어나는 반응입니다.","신생아의 발바닥을 간지럽히면 발가락을 부채처럼 쫙 펴는 반사이다":"발바닥에 자극을 주면 발가락을 활짝 벌리는 바빈스키 반사를 설명합니다.","아동은 취약한 피험자이므로 기관생명윤리위원회의 정규심의를 거쳐야 하며 연구윤리 원칙이 엄격하게 지켜져야 한다":"아동은 스스로 보호하기 어려워 위원회의 정식 심의를 받고 윤리 기준을 더 엄격하게 따릅니다.","아동의 발달을 사회적 상호작용과 문화로부터 분리할 수 없다":"비고츠키는 아이가 어른과 문화 속에서 주고받으며 발달한다고 보았습니다.","애착을 형성하기 위해서는 대상영속성이 획득되어야 한다":"양육자가 보이지 않아도 존재한다는 것을 알아야 특정 대상에 대한 애착이 생깁니다.","애착형성을 본능적 반응의 결과로 설명한다":"볼비는 영아가 생존을 위해 양육자에게 가까이 가려는 선천적 경향을 타고난다고 보았습니다.","언어를 이해하는 데 문제가 발생하는 장애이다":"베르니케 영역이 손상되면 말은 유창해도 남의 말을 이해하기 어렵습니다.","언어에 대한 지식의 부족으로 말을 하지 않는 것이 아니다":"선택적 함구증은 말하는 능력이 모자라서가 아니라 특정 상황에서 불안 때문에 말을 못 하는 것입니다.","여러 개의 독립적인 지능들로 구성되어 있다":"지능을 하나의 능력이 아니라 서로 별개로 작동하는 여러 능력의 묶음으로 봅니다.","여러 연령집단을 표집하여 일정한 기간 동안 반복 관찰한다":"횡단과 종단 방법을 합친 설계로, 연령 집단별로 일정 기간 되풀이해 관찰합니다.","역사적 혹은 문화적 맥락은 발달에 영향을 미친다":"개인이 살아가는 시대와 문화가 발달의 양상을 달라지게 합니다.","연구 과정에서 피험자 탈락, 연습효과 등이 연구결과를 왜곡할 수 있다":"장기 추적 중 참여자가 빠지거나 검사에 익숙해지면 결과가 실제 발달과 달라질 수 있습니다.","연구에 참여하는 모든 참여자는 다른 참여자들이 받는 유익한 처치를 동등하게 받을 권리가 있다":"통제집단이라도 효과가 확인된 처치를 받을 수 있게 해 참여자 간 불평등을 없애야 합니다.","연구 참여자들은 사생활을 보호받을 권리가 있으며 개인 정보는 철저히 보호되어야 한다":"참여자의 신상과 응답이 밖으로 새지 않도록 연구자가 비밀을 지켜야 합니다.","연령이 증가할수록 만족지연 능력이 증가한다":"자라면서 충동을 참는 힘이 커져 더 큰 보상을 위해 기다릴 수 있게 됩니다.","영아가 애착 대상에게서 떨어질 때 나타나는 불안반응이다":"애착이 형성된 뒤 양육자와 헤어질 때 울고 매달리는 반응이 분리불안입니다.","영아는 성인보다 많은 수의 시냅스를 갖고 있다":"영아기에 과잉 생성된 연결은 이후 경험에 따라 정리되므로 영아가 성인보다 더 많습니다.","영아의 공격성은 대체로 물건을 차지하기 위한 도구적 공격성이다":"영아는 해치려는 마음보다 원하는 물건을 얻으려고 밀치거나 빼앗습니다.","영아의 뇌는 성인의 뇌보다 가소성이 뛰어나다":"영아의 뇌는 경험에 따라 바뀌는 정도가 커서 손상을 입어도 회복할 가능성이 높습니다.","위험에 대한 반응으로 나타난다":"공포는 위협을 알아차릴 때 몸을 보호하려고 일어나는 정서 반응입니다.","유아기보다 아동기에 더 많이 발생한다":"이타적 행동은 조망 수용과 공감 능력이 자란 아동기에 더 자주 나타납니다.","유아는 사람들이 진짜로 느끼는 정서와":"유아의 정서 이해에 대해 설명하는 문장의 앞부분입니다.","유전적 요인에 의해 결정되는 지능이다":"교육이나 경험보다 타고난 바탕의 영향이 큰 유동지능의 특징입니다.","유지 되거나 향상될 수 있음":"교육과 경험이 계속되면 결정적 지능은 나이가 들어도 유지되거나 오를 수 있습니다.","이원적 사고에서 상대적 사고로 옮겨 간다고 본다":"옳고 그름 둘뿐이라는 흑백 사고에서 입장에 따라 달라진다는 사고로 발달합니다.","인간은 언어습득장치를 가지고 태어난다고 주장한다":"생득주의는 언어를 배우는 능력이 선천적으로 갖춰져 있다는 입장입니다.","인간의 모든 행동에는 그 원인이 있다는 심리적 결정론을 주장한다":"우연한 행동은 없고 모든 행동이 마음속 원인에서 비롯된다는 입장입니다.","인간의 정신적 지각 수준인 무의식, 전의식, 의식의 세 영역 중 무의식 세계를 가장 중시한다":"정신분석은 세 층 중에서도 의식되지 않는 무의식이 행동을 가장 크게 좌우한다고 봅니다.","인지적, 사회정서적, 신체적 발달은 상호작용한다":"발달 영역은 따로 일어나지 않고 서로 영향을 주고받으며 함께 변합니다.","일반요인(g)은 모든 유형의 지적 활동에 관여하는 일반적 능력임":"모든 지적 과제의 수행에 공통으로 작용하는 하나의 능력이 있다는 뜻입니다.","임신 28주경이 되면 태아는 자궁 밖에서 생존 가능하다":"이 무렵이면 폐와 뇌가 어느 정도 발달해 미숙아로 태어나도 살 수 있습니다.","임신 2개월부터 출생까지의 시기이다":"태내 발달 가운데 배아기 이후 출생 전까지의 긴 기간이 태아기입니다.","자녀에게 관심을 갖지 않고 자녀의 삶에 관여하지 않는다":"애정도 통제도 낮아 아이의 생활에 무관심한 양육 방식입니다.","자녀의 사회적 유능감을 높인다":"권위적 양육은 애정과 일관된 통제를 함께 주어 아이가 사회적으로 유능해지게 합니다.","자녀의 행동을 수용은 하지만 통제하지 않는다":"따뜻하게 받아 주지만 규칙과 제한을 두지 않는 양육 방식입니다.","자신과 상대방의 관점을 사회적 가치체계에 의해 판단할 수 있게 된다":"관점을 개인 차원이 아닌 사회의 가치 기준으로 평가하게 되는 사회적 조망 수용의 발달입니다.","자신의 행동이 모든 사람의 관심 대상이라고 생각한다":"자기가 늘 남의 이목을 끈다고 믿는 상상적 청중 현상이 나타납니다.","자아의 인식 이후에 나타난다":"수치심이나 죄책감 같은 정서는 자기 자신을 인식한 뒤에야 생겨납니다.","자의식을 지나치게 과장한 나머지":"청소년기 자의식 과잉을 설명하는 문장의 앞부분입니다.","전형적이고 평균적인 발달을 말한다":"규준적 발달은 대부분의 사람이 일정한 시기에 보이는 일반적 변화를 가리킵니다.","제한적이고 반복적인 행동 양식과 흥미, 활동을 보인다":"같은 행동을 되풀이하고 좁은 대상에만 몰두하는 것이 자폐스펙트럼장애의 핵심 증상입니다.","조기발견과 개입을 하게 되면 자폐스펙트럼장애가 지적장애로 이어지는 비율을 감소시킬 수 있다":"일찍 발견해 개입하면 자폐스펙트럼장애 아동이 지적장애를 함께 지니는 비율을 낮출 수 있다는 내용입니다.","종교, 문학 등의 지적 활동에 몰입함으로써 불안을 회피하려는 것":"감정을 직접 느끼는 대신 지적인 일에 몰두해 불안에서 벗어나려는 방어입니다.","주양육자에게 양가적 태도를 보인다":"저항애착 영아는 가까이하려 하면서도 화를 내고 저항하는 상반된 반응을 보입니다.","증상이 사회적ㆍ학업적 또는 직업적 기능의 질을 방해하거나 감소시킨다는 명확한 증거가 있다":"증상이 있더라도 일상 기능에 실제로 지장을 준다는 근거가 있어야 진단에 해당합니다.","지능은 문화권에 따라 다르게 정의될 수 있으며 각 하위 지능들의 상대적 중요성은 동일함":"문화마다 중요하게 여기는 지능이 달라질 수 있고 이론상 각 지능의 비중은 같습니다.","지능은 상호 독립적인 일곱 가지 하위요인으로 구성됨":"지능이 서로 독립적인 일곱 가지 기본 능력으로 이루어진다는 주장입니다.","진단을 위한 증상 9개 중 6개 이상이 최소 6개월 동안 발달수준에 적합하지 않아야 한다":"주의력결핍 과잉행동장애는 증상이 아홉 개 중 여섯 개 이상 반년 넘게 발달 수준에 맞지 않을 때 진단합니다.","진단의 지표가 되는 증상 9개 중 몇 개는 12세 이전에 나타난다":"어릴 때부터 있었던 문제임을 확인하기 위해 증상 일부가 12세 이전에 나타나야 합니다.","진단의 지표가 되는 증상 9개 중 몇 개는 2개 이상의 환경(가정, 학교, 대인관계 등)에서 나타난다":"한 장소만이 아니라 가정과 학교 같은 둘 이상의 환경에서 증상이 있어야 합니다.","진로발달 과정에서 자아개념은 중요한 요인이다":"수퍼는 자신을 어떤 사람으로 보느냐가 진로 선택과 발달에 큰 영향을 준다고 보았습니다.","질풍노도의 시기는 성ㆍ친밀감ㆍ안전 욕구 간의 충돌로 인해 일어난다":"설리반은 청소년의 혼란을 성과 친밀감과 안전이라는 욕구가 서로 부딪치기 때문이라고 설명했습니다.","청소년기보다 영아기에 뇌의 성장 급등이 이루어진다":"뇌가 가장 급격히 자라는 시기는 영아기이며 청소년기에는 그보다 완만합니다.","체계적으로 조합, 구성하는 조합적 추리 능력이 발달한다":"여러 요인을 체계적으로 짝지어 모든 경우를 따져 보는 추리가 가능해집니다.","출생 이후 전전두엽 피질의 활성화로 인지적 통제기능이 점차 향상된다":"전전두엽이 발달할수록 충동을 억제하고 주의를 조절하는 능력이 좋아집니다.","친사회적 행동에 대한 보상의 관찰은 친사회적 행동을 증진시킨다":"남이 돕고 칭찬받는 것을 보면 아이가 그 행동을 따라 하게 됩니다.","친사회적 행동으로 인한 손해가 보상보다 클 때 친사회적 행동은 감소한다":"비용과 이익을 따지는 관점에서 도움이 손해가 되면 사람은 돕는 행동을 줄입니다.","친사회적 행동은 초자아의 발달과 관련되어 있다":"정신분석에서는 도덕적 양심에 해당하는 초자아가 자라면서 남을 돕는 행동이 나타난다고 봅니다.","코로나 팬데믹은 규범적 역사관련 요인이다":"같은 시기의 많은 사람이 공통으로 겪은 사건이어서 규범적 역사관련 요인에 속합니다.","타인에게 고통이나 해를 가하는 것 자체가 목적이다":"상대가 아파하는 것이 곧 목표인 공격으로, 무언가를 얻기 위한 수단이 아닙니다.","태아기 동안 실제로 필요한 뉴런보다 훨씬 더 많은 뉴런이 생성된다":"뉴런이 넉넉히 만들어진 뒤 쓰이지 않는 것은 나중에 줄어드는 가지치기를 겪습니다.","투쟁-도피 반응은 교감신경계 활성화와 관계있다":"위협을 느끼면 교감신경이 활성화되어 맞서 싸우거나 도망치게 하는 반응이 일어납니다.","특정 발달 단계에서의 위기 극복에 실패하더라도 다음 단계로 발달이 진행된다":"에릭슨에서 위기를 해결하지 못해도 발달은 멈추지 않고 이어집니다.","프로이트(S. Freud)의 방어기제 중에는 더 성숙한 방어기제도 있다고 간주":"베일런트는 방어기제에도 미숙한 것과 성숙한 것이 있다고 구분했습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
